(()=>{
'use strict';
const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=n=>n==null?'Keine Angabe':new Intl.NumberFormat('de-DE',{style:'currency',currency:'EUR',maximumFractionDigits:2}).format(n);
const positive=n=>n!==null&&n!==''&&Number.isFinite(Number(n))&&Number(n)>0?Number(n):null;
let rows=[],page=1,controller=null,generation=0,loadedZip='',mapAllowed=false;
function values(){try{return JSON.parse(localStorage.getItem('immobrain-manual-market-values-v1')||'{}')[loadedZip]||{}}catch{return {}}}
function sqm(x){return positive(x.action==='mieten'?x.rent_per_square_meter:x.price_per_square_meter)||(positive(x.square_meter)&&positive(x.action==='mieten'?x.rent_price:x.price)?Number(x.action==='mieten'?x.rent_price:x.price)/Number(x.square_meter):null)}
function median(a){a=a.filter(n=>n!==null).sort((a,b)=>a-b);return a.length?(a[Math.floor(a.length/2)]+a[Math.floor((a.length-1)/2)])/2:null}
function merge(x){const identity=JSON.stringify([x.source,x.immo_id]);if(rows.some(r=>r.links.some(y=>JSON.stringify([y.source,y.immo_id])===identity)))return;const signature=r=>JSON.stringify([String(r.title||'').toLowerCase().replace(/\s+/g,' ').trim(),r.zipcode,r.typ,r.action,r.price,r.rent_price,r.square_meter,r.rooms]);const same=x.title&&positive(x.square_meter)&&rows.find(r=>r.source!==x.source&&signature(r)===signature(x));if(same)same.links.push(x);else rows.push({...x,links:[x]})}
function render(){const purchase=rows.filter(x=>x.action==='kaufen'),rent=rows.filter(x=>x.action==='mieten'),v=values();$('stats').innerHTML=[['Kaufangebote',purchase,'buy',v.purchase],['Mietangebote',rent,'rent',v.rent]].map(([label,items,cls,ref])=>`<article class="stat ${cls}"><h2>${label}</h2><strong>${items.length} Objekte</strong><p>Median: ${money(median(items.map(sqm)))} / m²${cls==='rent'?' monatlich':''}</p><small>Dein PLZ-Wert: ${money(positive(ref))} / m²${cls==='rent'?' monatlich':''}</small></article>`).join('')+`<article class="stat"><h2>Datengrundlage</h2><strong>PLZ ${esc(loadedZip)}</strong><p>${esc($('type').value)} · aktive Angebote</p><small>Median nur aus verfügbaren positiven Quadratmeterpreisen. Keine historischen Transaktionspreise.</small></article>`;$('legend').innerHTML=`<span class="buy-label">● ${purchase.length} Kaufangebote</span><span class="rent-label">● ${rent.length} Mietangebote</span><span>Gemeinsamer Lagebereich: PLZ ${esc(loadedZip)}</span>`;
const visible=rows.filter(x=>!$('deal').value||x.action===$('deal').value),pages=Math.max(1,Math.ceil(visible.length/50));page=Math.min(page,pages);$('list').innerHTML=visible.slice((page-1)*50,page*50).map(x=>{const rental=x.action==='mieten';return `<article class="listing"><small class="${rental?'rent-label':'buy-label'}">${rental?'Miete':'Kauf'}</small><h3>${esc(x.title||'Immobilie')}</h3><p>${esc(String(x.zipcode??'').padStart(5,'0'))} ${esc(x.city)}</p><div class="details"><span>${positive(x.square_meter)??'–'} m²</span><span>${positive(x.rooms)??'–'} Zimmer</span><strong>${money(positive(rental?x.rent_price:x.price))}${rental?' Kaltmiete / Monat':''}</strong><span>${money(sqm(x))} / m²</span></div><div class="portal-links">${x.links.map(y=>{try{const url=new URL(y.url);if(url.protocol!=='https:')return '';return `<a href="${esc(url.href)}" target="_blank" rel="noopener noreferrer">${esc(y.source||'Originalinserat')} ↗</a>`}catch{return ''}}).join('')}</div></article>`}).join('')||'<p>Keine passenden Angebote geladen.</p>';$('page').textContent=`Seite ${page} von ${pages}`;$('prev').disabled=page<=1;$('next').disabled=page>=pages}
async function map(zip,token){if(!mapAllowed||!/^\d{5}$/.test(zip))return;$('map').textContent='Karte wird geladen …';try{const r=await fetch('/postcode-geo.csv');if(!r.ok)throw Error();const line=(await r.text()).split(/\r?\n/).find(s=>s.startsWith(zip+','));if(!line)throw Error();const [,a,b]=line.split(','),lat=Number(a),lon=Number(b);if(!Number.isFinite(lat)||!Number.isFinite(lon)||lat<47||lat>56||lon<5||lon>16)throw Error();if(token!==generation)return;const url=new URL('https://www.openstreetmap.org/export/embed.html');url.searchParams.set('bbox',[lon-.045,lat-.025,lon+.045,lat+.025].join(','));url.searchParams.set('layer','mapnik');url.searchParams.set('marker',lat+','+lon);const frame=document.createElement('iframe');frame.title='Ungefährer Lagebereich der PLZ '+zip;frame.referrerPolicy='no-referrer';frame.src=url.href;$('map').replaceChildren(frame);const note=document.createElement('p');note.textContent='Marker = PLZ-Mitte. Keine Objektposition. Kartendaten © OpenStreetMap-Mitwirkende.';$('map').append(note)}catch{if(token===generation)$('map').textContent='Für diese PLZ ist derzeit keine Kartenposition verfügbar.'}}
$('map-load').onclick=()=>{mapAllowed=true;if(loadedZip)map(loadedZip,generation);else $('map').textContent='Bitte zuerst Angebote für eine PLZ laden.'};
$('market-form').onsubmit=async e=>{e.preventDefault();if(!$('market-form').reportValidity())return;controller?.abort();const token=++generation;controller=new AbortController();const signal=controller.signal;loadedZip=$('zip').value;const type=$('type').value;rows=[];page=1;$('cancel').hidden=false;$('title').textContent='Marktübersicht · '+loadedZip;history.replaceState(null,'','?plz='+loadedZip);if(mapAllowed)map(loadedZip,token);render();let complete=false;try{for(let p=1;p<=1000;p++){$('status').textContent=`Kauf- und Mietangebote werden geladen · ${rows.length} Objekte bisher …`;const r=await fetch('/api/somantic/search',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({place:loadedZip,type,deal:'',page:p}),signal});const data=await r.json();if(token!==generation)return;if(!r.ok)throw Error(data.error||'Abruf fehlgeschlagen.');for(const x of data.listings||[])merge(x);render();if(!data.hasMore){complete=true;break}}$('status').textContent=complete?`${rows.length} Objekte geladen · Stand: ${new Date().toLocaleString('de-DE')} · aktive Angebote.`:'Sicherheitsgrenze erreicht. Ergebnisse unvollständig.'}catch(err){if(token!==generation)return;$('status').textContent=(err.name==='AbortError'?'Abruf abgebrochen.':err.message)+' Ergebnisse sind möglicherweise unvollständig.'}finally{if(token===generation){$('cancel').hidden=true;controller=null}}};
$('cancel').onclick=()=>controller?.abort();$('deal').onchange=()=>{page=1;render()};$('prev').onclick=()=>{page--;render()};$('next').onclick=()=>{page++;render()};window.addEventListener('storage',e=>{if(e.key==='immobrain-manual-market-values-v1')render()});const zip=new URLSearchParams(location.search).get('plz');if(/^\d{5}$/.test(zip||''))$('zip').value=zip;
})();
